import React from "react";
import { useNavigate, useParams } from "react-router-dom";

const Sidebar = ({ showButton = true }) => {
  const navigate = useNavigate();
  const { id } = useParams();

  const modulos = [
    "Aula 01 – Bem Vindo",
    "Aula 02 – Liderança",
    "Aula 03 – Desenvolvimento",
    "Aula 04 – Propósito",
    "Aula 05 – Estilos",
    "Aula 06 – Bônus",
  ];

  return (
    <aside className="w-72 bg-gradient-to-b from-[#B95758] to-[#e14d3a] text-white p-6 fixed top-0 left-0 h-full flex flex-col justify-between">
      <div>
        <h2 className="text-lg font-bold mb-6 uppercase">Módulos</h2>
        <ul className="space-y-3 text-sm">
          {modulos.map((modulo, i) => (
            <li key={i} className="hover:text-yellow-200 cursor-pointer">
              {modulo}
            </li>
          ))}
        </ul>
      </div>

      {/* Botão "Material de Apoio" (opcional) */}
      {showButton && (
        <button
          onClick={() => navigate(`/materiais/${id || 1}`)}
          className="w-full bg-white text-[#B95758] font-semibold py-2 rounded-md hover:bg-gray-100 transition shadow-sm"
        >
          Material de Apoio
        </button>
      )}
    </aside>
  );
};

export default Sidebar;
